//go:build linux
// +build linux

// Code generated by gen-gdrcopy from gdrapi.h. DO NOT EDIT.

package gdrcopy

import (
	"os"
	"testing"
)

// requireLibrary loads libgdrapi or explains why it could not.
//
// A skip here is not evidence that the binding works; it is evidence that
// nothing checked it. GDRCOPY_REQUIRE_LIBRARY=1 makes the absence a failure.
func requireLibrary(t *testing.T) {
	t.Helper()
	if err := Load(""); err != nil {
		if os.Getenv("GDRCOPY_REQUIRE_LIBRARY") != "" {
			t.Fatalf("GDRCOPY_REQUIRE_LIBRARY is set but libgdrapi could not be loaded: %v", err)
		}
		t.Skipf("libgdrapi is not installed here, so nothing in this test was checked. "+
			"Install NVIDIA gdrcopy or point GDRCOPY_LIB_PATH at libgdrapi.so.2, and set "+
			"GDRCOPY_REQUIRE_LIBRARY=1 to make this a failure instead of a skip: %v", err)
	}
}

// TestBaseSymbolsResolve checks the symbols every gdrcopy 2.x release exports.
// A failure here means the binding names a symbol libgdrapi does not have,
// which no amount of run-time version checking can excuse: the soname is
// libgdrapi.so.2 for all of them.
func TestBaseSymbolsResolve(t *testing.T) {
	requireLibrary(t)
	for _, symbol := range []string{
		"gdr_open",
		"gdr_close",
		"gdr_pin_buffer",
		"gdr_unpin_buffer",
		"gdr_get_callback_flag",
		"gdr_map",
		"gdr_unmap",
		"gdr_copy_to_mapping",
		"gdr_copy_from_mapping",
		"gdr_runtime_get_version",
		"gdr_driver_get_version",
	} {
		if !Has(symbol) {
			t.Errorf("%s did not resolve in %s, which every gdrcopy 2.x release exports", symbol, Path())
		}
	}
}

// TestVersionedSymbols reports which of the later entry points the loaded
// library has. None of them is required: the soname does not change across
// 2.x, so a 2.0 library is a legitimate thing to find. Calling one it lacks
// returns *SymbolError, which is the contract this records.
func TestVersionedSymbols(t *testing.T) {
	requireLibrary(t)
	major, minor, err := RuntimeGetVersion()
	if err != nil {
		t.Fatalf("RuntimeGetVersion: %v", err)
	}
	t.Logf("libgdrapi %d.%d at %s", major, minor, Path())
	for _, tt := range []struct {
		symbol string
		since  string
	}{
		{"gdr_pin_buffer_v2", "2.5"},
		{"gdr_get_info_v2", "2.4"},
		{"gdr_map_v2", "2.5"},
		{"gdr_get_attribute", "2.5"},
		{"gdr_get_mapping_type_string", "2.5"},
	} {
		if Has(tt.symbol) {
			t.Logf("%s present (added in gdrcopy %s)", tt.symbol, tt.since)
			continue
		}
		t.Logf("%s absent; this library predates gdrcopy %s and calls into it return *SymbolError", tt.symbol, tt.since)
		if err := checkLibSym(tt.symbol); err == nil {
			t.Errorf("%s is absent but checkLibSym reported it callable", tt.symbol)
		}
	}
}

// TestGetInfoIsNotBound checks that the binding did not pick up the obsolete
// gdr_get_info symbol.
//
// gdrapi.h defines gdr_get_info as a macro for gdr_get_info_v2, but libgdrapi
// still exports a function of that name taking the shorter v1 struct. If this
// package ever registers it, a call would write eight bytes fewer than Info
// expects and leave MappingType holding whatever was there before, with no
// error anywhere.
func TestGetInfoIsNotBound(t *testing.T) {
	requireLibrary(t)
	if Has("gdr_get_info") {
		t.Error("gdr_get_info is registered; it is the obsolete v1 ABI and must not be bound")
	}
}

// TestMappingTypeStrings compares the library's own names for the mapping
// types against the enumerators generated from the header, which is a check
// that the two agree about what the values mean.
func TestMappingTypeStrings(t *testing.T) {
	requireLibrary(t)
	if !Has("gdr_get_mapping_type_string") {
		t.Skip("libgdrapi predates gdr_get_mapping_type_string (gdrcopy 2.5); nothing was checked")
	}
	for _, mt := range []MappingType{MappingTypeNone, MappingTypeWc, MappingTypeCaching, MappingTypeDevice} {
		s, err := MappingTypeString(mt)
		if err != nil {
			t.Errorf("MappingTypeString(%v): %v", mt, err)
			continue
		}
		if s == "" {
			t.Errorf("MappingTypeString(%v) returned an empty string", mt)
		}
		t.Logf("%v is %q to libgdrapi", mt, s)
	}
}
